get_ipython().run_cell_magic('manim', 'PriceControls', '\nclass PriceControls(GraphScene):\n    CONFIG = {\n        "x_axis_label": "$Q_d$",\n        "y_axis_label": "$P$",\n        "x_min": 0,\n        "x_max": 100,\n        "y_min": 0,\n        "y_max": 10,\n        "x_axis_width": FRAME_HEIGHT,\n        "y_axis_height":FRAME_HEIGHT / 2,\n        "x_labeled_nums": [],\n        "y_labeled_nums": [],\n        "y_tick_frequency": 10,\n        "x_tick_frequency": 100,\n        "graph_origin": np.array((-FRAME_X_RADIUS + 2*LARGE_BUFF, -FRAME_Y_RADIUS + 2*LARGE_BUFF, 0)),\n        "demand_color": BLUE,\n        "supply_color": ORANGE,\n        "expenditure_color": GREEN,\n        "cs_color": PINK,\n        "ps_color": YELLOW,\n        "surplus_color": BLUE,\n        "pq_color": RED,\n        "axes_color": GREY,\n        "dwl_color": GREY,\n    }\n\n    def construct(self):\n        self.intro_sequence()\n        self.wait(3)\n        #self.create_quantity_demanded(4)\n        #self.wait(3)\n        #self.create_quantity_supplied(4)\n        #self.wait(3)\n        self.show_equilibrium()\n        self.wait(3)\n        self.create_quantity_demanded(4)\n        self.create_quantity_supplied(4)\n        self.legal_interval(10,4)\n        self.update_quantity(8,8)\n        self.legal_interval(10,8)\n        self.quantity_exchanged(8,8)\n        self.show_cs(8)\n        self.show_ps(8,8)\n        self.show_dwl(8,8)\n        self.update_surplus(8,8)\n        self.legal_interval(0,5)\n        self.update_quantity(5,5)\n        self.update_surplus(5,5)\n        \n    def DemandQ(self, priceD):\n        return 100 - 10*priceD\n    \n    def DemandP(self,quantityD):\n        return (10 - quantityD/10)\n    \n    def SupplyQ(self, priceS):\n        return 10*priceS - 20\n    \n    def SupplyP(self,quantityS):\n        return 2 + quantityS /10\n                \n    def intro_sequence(self):\n        title = TextMobject("Tutorial 3.4 | Price Controls").scale(1.5)\n        self.play(FadeIn(title))\n        self.wait(1)\n        transform_title = TextMobject("Tutorial 3.4 | Price Controls and Efficiency").scale(1.2)\n        transform_title.to_corner(UP)\n        self.play(\n            Transform(title, transform_title))\n        self.wait(3)\n        self.setup_axes(animate=True)\n\n        \n    def show_equilibrium(self):\n        DemandCurve = self.get_graph(self.DemandP, self.demand_color, x_min=0, x_max=100)\n        SupplyCurve = self.get_graph(self.SupplyP, self.supply_color, x_min=0, x_max=80)\n        \n        eqp1 = self.coords_to_point(0, 6)\n        eqp2 = self.coords_to_point(40, 6)\n        eqp3 = self.coords_to_point(40, 0)\n        \n        horzLineEq = DashedVMobject(Line(eqp1,eqp2, color=self.axes_color))\n        vertLineEq = DashedVMobject(Line(eqp2,eqp3, color=self.axes_color))\n        \n        self.play(ShowCreation(DemandCurve))\n        self.play(ShowCreation(SupplyCurve))\n        self.play(ShowCreation(horzLineEq))\n        self.play(ShowCreation(vertLineEq))\n        \n    \n    def create_quantity_demanded(self,price):\n        DemandCurve = self.get_graph(self.DemandP, self.demand_color, x_min=0, x_max=100)\n        quantityD = self.DemandQ(price)\n\n        p1 = self.coords_to_point(0, price)\n        p2 = self.coords_to_point(quantityD, price)\n        p3 = self.coords_to_point(quantityD, 0)\n        \n        horzLineD = Line(p1,p2, color=self.pq_color)\n        priceDDesc = TextMobject("$p=$"+str(price)).scale(0.7)\n        priceDDesc.next_to(horzLineD, LEFT)\n        \n        pointD = Dot(p2, color=self.pq_color)\n        \n        vertLineD = DashedVMobject(Line(p2,p3, color=self.pq_color))\n        quantityDDesc = TextMobject("$q_d=$"+str(quantityD)).scale(0.7)\n        quantityDDesc.move_to(self.coords_to_point(quantityD, -0.1),UP)\n\n        #self.play(ShowCreation(DemandCurve))\n        #self.wait(1)\n        self.play(ShowCreation(horzLineD),FadeIn(priceDDesc))\n        self.add(pointD)\n        self.play(ShowCreation(vertLineD),FadeIn(quantityDDesc))\n        \n        self.horzLineD = horzLineD\n        self.priceDDesc = priceDDesc\n        self.pointD = pointD\n        self.vertLineD = vertLineD\n        self.quantityDDesc = quantityDDesc\n        \n    \n    def create_quantity_supplied(self,price):\n        SupplyCurve = self.get_graph(self.SupplyP, self.supply_color, x_min=0, x_max=80)\n        quantityS = self.SupplyQ(price)\n        quantityD = self.DemandQ(price)\n        quantityXL = max(quantityS,quantityD)\n        \n        p1 = self.coords_to_point(0, price)\n        p2 = self.coords_to_point(quantityXL, price)\n        p3 = self.coords_to_point(quantityS, price)\n        p4 = self.coords_to_point(quantityS, 0)\n\n        horzLineS = Line(p1,p2, color=self.pq_color)\n        \n        priceSDesc = TextMobject("$p=$ "+str(price)).scale(0.7)\n        priceSDesc.next_to(horzLineS, LEFT)\n        \n        priceSDesc = TextMobject("$p=$ "+str(price)).scale(0.7)\n        priceSDesc.next_to(horzLineS, LEFT)\n        \n        pointS = Dot(p3, color=self.pq_color)\n        \n        vertLineS = DashedVMobject(Line(p3,p4, color=self.pq_color))\n        quantitySDesc = TextMobject("$q_s=$ "+str(quantityS)).scale(0.7)\n        quantitySDesc.move_to(self.coords_to_point(quantityS, -1),UP)\n                \n        #self.play(ShowCreation(SupplyCurve))\n        #self.wait(1)\n        self.play(Transform(self.horzLineD,horzLineS))\n        self.add(pointS)\n        self.play(ShowCreation(vertLineS),FadeIn(quantitySDesc))\n        \n        self.SupplyCurve = SupplyCurve\n        #self.horzLineS = horzLineS\n        self.priceSDesc = priceSDesc\n        self.pointS = pointS\n        self.vertLineS = vertLineS\n        self.quantitySDesc = quantitySDesc\n    \n    \n    def update_quantity(self,priceS,priceB):\n        quantityS = self.SupplyQ(priceS)\n        quantityD = self.DemandQ(priceB)\n        quantityXL = max(quantityS,quantityD)\n        \n        hp1 = self.coords_to_point(0, priceS)\n        hp2 = self.coords_to_point(quantityXL, priceS)        \n        horzLineS = Line(hp1,hp2, color=self.pq_color)\n        priceSDesc = TextMobject("$p=$ "+str(priceB)).scale(0.7)\n        priceSDesc.next_to(horzLineS, LEFT)\n\n        #newPriceSDesc = TextMobject("$p_s=$"+str(newPriceS)).scale(0.8)\n        #newPriceSDesc.next_to(newHorzLineS, LEFT)\n\n        vp1 = self.coords_to_point(quantityS, priceS)\n        vp2 = self.coords_to_point(quantityS, 0)\n        pointS = Dot(vp1, color=self.pq_color)\n        vertLineS = DashedVMobject(Line(vp1,vp2, color=self.pq_color))\n        \n        quantitySDesc = TextMobject("$q_s=$ "+str(quantityS)).scale(0.7)\n        quantitySDesc.move_to(self.coords_to_point(quantityS, -1),UP)\n        \n        vp3 = self.coords_to_point(quantityD, priceB)\n        vp4 = self.coords_to_point(quantityD, 0)\n        pointD = Dot(vp3, color=self.pq_color)\n        vertLineD = DashedVMobject(Line(vp3,vp4, color=self.pq_color))\n        \n        quantityDDesc = TextMobject("$q_d=$ "+str(quantityD)).scale(0.7)\n        quantityDDesc.move_to(self.coords_to_point(quantityD, -0.1),UP)\n        \n        self.play(Transform(self.horzLineD,horzLineS),\n                  Transform(self.pointS,pointS),\n                  Transform(self.vertLineS,vertLineS),\n                  #Transform(self.priceSDesc,newPriceSDesc),\n                  Transform(self.quantitySDesc,quantitySDesc),\n                  #Transform(self.horzLineD,horzLineD),\n                  Transform(self.pointD,pointD),\n                  Transform(self.vertLineD,vertLineD),\n                  Transform(self.priceDDesc,priceSDesc),\n                  Transform(self.quantityDDesc,quantityDDesc))\n    \n    \n    def quantity_exchanged(self, priceB, priceS):\n        quantityD = self.DemandQ(priceB)\n        quantityS = self.SupplyQ(priceS)\n        \n        qL = self.coords_to_point(0, -2)\n        qU = self.coords_to_point(min(quantityD,quantityS), -2)\n        \n        quantityExchanged = Line(qL,qU, color=self.axes_color)\n        quantityExchLabel = TextMobject("Quantity Exchanged").scale(0.6)\n        quantityExchLabel.add_updater(lambda d: d.next_to(quantityExchanged,DOWN))\n\n        self.play(ShowCreation(quantityExchanged))\n        self.add(quantityExchLabel)\n        self.wait(1)\n        \n        self.quantityExchanged = quantityExchanged\n        self.quantityExchLabel = quantityExchLabel\n    \n    \n    def legal_interval(self, priceU, priceL):\n        #try:\n        #    self.play(FadeOut(self.legalInterval,legalInterval), Transform(self.legalIntervalLabel,legalIntervalLabel))\n        pL = self.coords_to_point(-18, priceL+0.1)\n        pU = self.coords_to_point(-18, priceU-0.1)\n        \n        legalInterval = Line(pL,pU, color=self.axes_color)\n        legalIntervalLabel = TextMobject("Legal Interval").scale(0.7)\n        legalIntervalLabel.add_updater(lambda d: d.next_to(legalInterval,LEFT))\n        legalIntervalLabel.rotate(TAU/4)\n        \n        try:\n            self.play(Transform(self.legalInterval,legalInterval), Transform(self.legalIntervalLabel,legalIntervalLabel))\n        \n        except:\n            self.play(ShowCreation(legalInterval))\n            self.add(legalIntervalLabel)\n            self.legalInterval = legalInterval\n            self.legalIntervalLabel = legalIntervalLabel\n        \n        \n    def show_cs(self, priceB):\n        quantityD = self.DemandQ(priceB)\n        \n        dx1 = self.coords_to_point(105, 8)\n        dx2 = self.coords_to_point(105, 10)\n        surplusDesc = Line(dx1,dx2, color=self.surplus_color)\n        \n        a = self.coords_to_point(0, 10)\n        b = self.coords_to_point(quantityD, priceB)\n        c = self.coords_to_point(quantityD, priceB)\n        d = self.coords_to_point(0, priceB)\n        cs = Polygon(a,b,c,d, fill_opacity = 0.2, fill_color = self.cs_color, color=self.cs_color)\n        \n        self.play(FadeIn(cs),FadeIn(surplusDesc))\n        \n        csAreaNumber = TextMobject(str(int((10-priceB)*quantityD/2)))\n        csAreaNumber.move_to(self.coords_to_point(3, priceB + (10 - priceB)/3), LEFT)\n        csAreaNumber.set_color(self.cs_color)\n        \n        surplusLabel = TextMobject("CS")\n        surplusLabel.next_to(surplusDesc,LEFT)\n        surplusLabel.set_color(self.cs_color)\n        \n        csDescNumber = TextMobject(str(int((10-priceB)*quantityD/2)))\n        csDescNumber.next_to(surplusDesc, RIGHT)\n        csDescNumber.set_color(self.cs_color)\n        \n        self.play(FadeIn(csAreaNumber))\n        self.play(Transform(csAreaNumber,csDescNumber),FadeIn(surplusLabel))\n        self.surplusDesc = surplusDesc\n        self.csDescNumber = csDescNumber\n        self.cs = cs\n        self.csAreaNumber = csAreaNumber\n        self.surplusLabel = surplusLabel\n        self.wait(1)\n        \n    \n    def show_ps(self, priceS, priceB):\n        quantityS = self.SupplyQ(priceS)\n        quantityD = self.DemandQ(priceB)\n        quantityX = min(quantityS,quantityD)\n        \n        wtsX = self.SupplyP(quantityX)            \n        wtbX = self.DemandP(quantityX)\n        \n        hp3 = self.coords_to_point(0, wtsX)\n        hp4 = self.coords_to_point(quantityX, wtsX)\n        wtsXLine = DashedVMobject(Line(hp3,hp4, color=self.axes_color))\n        hp3 = self.coords_to_point(0, wtbX)\n        hp4 = self.coords_to_point(quantityX, wtbX)\n        wtbXLine = DashedVMobject(Line(hp3,hp4, color=self.axes_color))\n        \n        self.play(FadeIn(wtsXLine),FadeIn(wtbXLine))\n        self.wtsXLine = wtsXLine\n        self.wtbXLine = wtbXLine\n\n        a = self.coords_to_point(0, 2)\n        b = self.coords_to_point(0, priceS)\n        c = self.coords_to_point(quantityX, priceS)\n        d = self.coords_to_point(quantityX, wtsX)\n        ps = Polygon(a,b,c,d, fill_opacity = 0.2, fill_color = self.ps_color, color=self.ps_color)\n\n        \n        self.play(FadeIn(ps))\n        \n        psAreaNumber = TextMobject(str(int((priceS-(2+wtsX)/2)*quantityX)))\n        psAreaNumber.move_to(self.coords_to_point(3, 3*(2 + priceS)/5), LEFT)\n        psAreaNumber.set_color(self.ps_color)\n        \n        psDescNumber = TextMobject(" + "+str(int((priceS-(2+wtsX)/2)*quantityX)))\n        psDescNumber.next_to(self.csAreaNumber)\n        psDescNumber.set_color(self.ps_color)\n        \n        surplusAreaNumber = TextMobject(\' = \'+str(int(((10+wtbX)/2 - (2+wtsX)/2) * quantityX)))\n        surplusAreaNumber.next_to(psDescNumber)\n        surplusAreaNumber.set_color(self.surplus_color)\n        \n        surplusLabel = TextMobject("TS")\n        surplusLabel.next_to(self.surplusDesc,LEFT)\n        surplusLabel.set_color(self.surplus_color)\n        \n        self.play(FadeIn(psAreaNumber))\n        self.play(Transform(self.surplusLabel,surplusLabel),Transform(psAreaNumber,psDescNumber))\n        self.play(FadeIn(surplusAreaNumber))\n        self.ps = ps\n        self.psAreaNumber = psAreaNumber\n        self.psDescNumber = psDescNumber\n        self.surplusAreaNumber = surplusAreaNumber\n        self.wait(1)\n        \n        \n    def show_dwl(self,priceS,priceB):\n        \n        quantityS = self.SupplyQ(priceS)\n        quantityD = self.DemandQ(priceB)\n        quantityX = min(quantityS,quantityD)\n        \n        wtsX = self.SupplyP(quantityX)\n        wtbX = self.DemandP(quantityX)\n        \n        a = self.coords_to_point(40, 6)\n        b = self.coords_to_point(quantityX, wtbX)\n        c = self.coords_to_point(quantityX, wtsX)\n        d = self.coords_to_point(40, 6)\n        dwl = Polygon(a,b,c,d, fill_opacity = 0.2, fill_color = GREY, color=GREY)\n        dwlAreaNumber = TextMobject(str(int((wtbX - wtsX)*(40 - quantityX)/2))).scale(0.8)\n        dwlAreaNumber.move_to(self.coords_to_point(quantityX+1, 6), LEFT)\n        \n        dx1 = self.coords_to_point(105, 5)\n        dx2 = self.coords_to_point(105, 7)\n        dwlDesc = Line(dx1,dx2, color=self.dwl_color)\n        \n        dwlLabel = TextMobject("DWL")\n        dwlLabel.next_to(dwlDesc,LEFT)\n        dwlLabel.set_color(self.dwl_color)\n        \n        dwlDescNumber = TextMobject(str(int((wtbX - wtsX)*(40 - quantityX)/2)))\n        dwlDescNumber.next_to(dwlDesc, RIGHT)\n        dwlDescNumber.set_color(self.dwl_color)\n        \n        self.play(FadeIn(dwl),FadeIn(dwlAreaNumber))\n        self.play(FadeIn(dwlDesc),FadeIn(dwlLabel),Transform(dwlAreaNumber,dwlDescNumber))\n        \n        self.dwlAreaNumber = dwlAreaNumber\n        self.dwl = dwl\n        self.dwlDesc = dwlDesc\n        self.dwlLabel = dwlLabel\n        \n    def update_surplus(self,priceS,priceB):\n        \n        quantityS = self.SupplyQ(priceS)\n        quantityD = self.DemandQ(priceB)\n        quantityX = min(quantityS,quantityD)\n        quantityXL = max(quantityS,quantityD)\n        \n        qL = self.coords_to_point(0, -2)\n        qU = self.coords_to_point(quantityX, -2)\n        quantityExchanged = Line(qL,qU, color=self.axes_color)\n        \n        wtsX = self.SupplyP(quantityX)\n        wtbX = self.DemandP(quantityX)\n        \n        hp1 = self.coords_to_point(0, priceB)\n        hp2 = self.coords_to_point(quantityXL, priceB)\n        #horzLineS = DashedVMobject(Line(p1,p2, color=self.pq_color))\n        horzLineD = Line(hp1,hp2, color=self.pq_color)\n        \n        hp3 = self.coords_to_point(0, wtsX)\n        hp4 = self.coords_to_point(quantityX, wtsX)\n        wtsXLine = DashedVMobject(Line(hp3,hp4, color=self.axes_color))\n        hp3 = self.coords_to_point(0, wtbX)\n        hp4 = self.coords_to_point(quantityX, wtbX)\n        wtbXLine = DashedVMobject(Line(hp3,hp4, color=self.axes_color))\n        \n        p1 = self.coords_to_point(quantityS, priceS)\n        p2 = self.coords_to_point(quantityS, 0)\n        \n        #newPriceSDesc = TextMobject("$p_s=$"+str(newPriceS)).scale(0.8)\n        #newPriceSDesc.next_to(newHorzLineS, LEFT)\n        pointS = Dot(p1, color=self.pq_color)\n        \n        vertLineS = DashedVMobject(Line(p1,p2, color=self.pq_color))\n        quantitySDesc = TextMobject("$q_s=$ "+str(quantityS)).scale(0.7)\n        quantitySDesc.move_to(self.coords_to_point(quantityS, -1),UP)\n        \n        p1 = self.coords_to_point(quantityD, priceB)\n        p2 = self.coords_to_point(quantityD, 0)\n        \n        priceDDesc = TextMobject("$p=$ "+str(priceB)).scale(0.7)\n        priceDDesc.next_to(horzLineD, LEFT)\n        pointD = Dot(p1, color=self.pq_color)\n        \n        vertLineD = DashedVMobject(Line(p1,p2, color=self.pq_color))\n        quantityDDesc = TextMobject("$q_d=$ "+str(quantityD)).scale(0.7)\n        quantityDDesc.move_to(self.coords_to_point(quantityD, -0.1),UP)\n        \n        a = self.coords_to_point(0, 10)\n        b = self.coords_to_point(quantityX, wtbX)\n        c = self.coords_to_point(quantityX, priceB)\n        d = self.coords_to_point(0, priceB)\n        cs = Polygon(a,b,c,d, fill_opacity = 0.2, fill_color = self.cs_color, color=self.cs_color)\n        csAreaNumber = TextMobject(str(int(((10+wtbX)/2-priceB)*quantityX)))\n        csAreaNumber.next_to(self.surplusDesc,RIGHT)\n        csAreaNumber.set_color(self.cs_color)\n        \n        a = self.coords_to_point(0, 2)\n        b = self.coords_to_point(0, priceS)\n        c = self.coords_to_point(quantityX, priceS)\n        d = self.coords_to_point(quantityX, wtsX)\n        ps = Polygon(a,b,c,d, fill_opacity = 0.2, fill_color = self.ps_color, color=self.ps_color)\n        psAreaNumber = TextMobject(" + "+str(int((priceS-(2+wtsX)/2)*quantityX)))\n        psAreaNumber.next_to(csAreaNumber,RIGHT)\n        psAreaNumber.set_color(self.ps_color)\n\n        a = self.coords_to_point(40, 6)\n        b = self.coords_to_point(quantityX, wtbX)\n        c = self.coords_to_point(quantityX, wtsX)\n        d = self.coords_to_point(40, 6)\n        dwl = Polygon(a,b,c,d, fill_opacity = 0.2, fill_color = GREY, color=GREY)\n        \n        surplusAreaNumber = TextMobject(\' = \'+str(int(((10+wtbX)/2 - (2+wtsX)/2) * quantityX)))\n        surplusAreaNumber.next_to(psAreaNumber,RIGHT)\n        surplusAreaNumber.set_color(self.surplus_color)\n        \n        dwlAreaNumber = TextMobject(str(int((wtbX - wtsX)*(40 - quantityX)/2)))\n        dwlAreaNumber.next_to(self.dwlDesc, RIGHT)\n        dwlAreaNumber.set_color(self.dwl_color)\n      \n        self.play(Transform(self.wtsXLine,wtsXLine),\n                  Transform(self.wtbXLine,wtbXLine),\n                  #Transform(self.horzLineS,horzLineS),\n                  Transform(self.pointS,pointS),\n                  Transform(self.vertLineS,vertLineS),\n                  #Transform(self.priceSDesc,newPriceSDesc),\n                  Transform(self.quantitySDesc,quantitySDesc),\n                  Transform(self.horzLineD,horzLineD),\n                  Transform(self.pointD,pointD),\n                  Transform(self.vertLineD,vertLineD),\n                  Transform(self.priceDDesc,priceDDesc),\n                  Transform(self.quantityDDesc,quantityDDesc),\n                  Transform(self.quantityExchanged,quantityExchanged),\n                  Transform(self.cs,cs),\n                  Transform(self.csAreaNumber,csAreaNumber),\n                  Transform(self.ps,ps),\n                  Transform(self.psAreaNumber,psAreaNumber),\n                  #Transform(self.csDescNumber,csDescNumber),\n                  #Transform(self.psDescNumber,psDescNumber),\n                  Transform(self.surplusAreaNumber,surplusAreaNumber),\n                  Transform(self.dwlAreaNumber,dwlAreaNumber),\n                  Transform(self.dwl,dwl))\n        \n        self.wait(3)\n        self.play(FadeOut(self.wtsXLine),\n                  FadeOut(self.wtbXLine),\n                  #Transform(self.horzLineS,horzLineS),\n                  FadeOut(self.pointS),\n                  FadeOut(self.vertLineS),\n                  #Transform(self.priceSDesc,newPriceSDesc),\n                  FadeOut(self.quantitySDesc),\n                  FadeOut(self.horzLineD),\n                  FadeOut(self.pointD),\n                  FadeOut(self.vertLineD),\n                  FadeOut(self.priceDDesc),\n                  FadeOut(self.quantityDDesc),\n                  FadeOut(self.quantityExchanged),\n                  FadeOut(self.cs),\n                  FadeOut(self.csAreaNumber),\n                  FadeOut(self.ps),\n                  FadeOut(self.psAreaNumber),\n                  #Transform(self.csDescNumber,csDescNumber),\n                  #Transform(self.psDescNumber,psDescNumber),\n                  FadeOut(self.surplusAreaNumber),\n                  FadeOut(self.dwlAreaNumber),\n                  FadeOut(self.dwl))\n\n        \n    def summary(self):\n        SupplyCurve = self.get_graph(self.SupplyP, self.supply_color, x_min=0, x_max=60)\n        self.play(FadeOut(self.csAreaNumber),\n                  FadeOut(self.csDescNumber),\n                  FadeOut(self.psAreaNumber),\n                  FadeOut(self.surplusAreaNumber),\n                  FadeOut(self.surplusDesc),\n                  FadeOut(self.surplusLabel),\n                  FadeOut(self.dwlAreaNumber),\n                  FadeOut(self.dwlLabel),\n                  FadeOut(self.dwlDesc))\n        self.play(Transform(self.SupplyCurve,SupplyCurve))\n        \n        result = TextMobject("Equilibrium maximizes welfare")\n        result.move_to(self.coords_to_point(65, 10), LEFT)\n        result1 = TextMobject("in private goods markets")\n        result1.move_to(self.coords_to_point(70, 8.5), LEFT)\n        self.play(FadeIn(result),FadeIn(result1))\n        self.wait(2)\n        self.play(FadeOut(result),FadeOut(result1))\n        summary = TextMobject("Total Surplus is found")\n        summary.move_to(self.coords_to_point(65, 10), LEFT)\n        self.play(FadeIn(summary))\n        summary1 = TextMobject("1) Between S and D curves")\n        summary1.move_to(self.coords_to_point(70, 8), LEFT)\n        self.play(FadeIn(summary1))\n        summary2 = TextMobject("2) Inside quantity")\n        summary2.move_to(self.coords_to_point(70, 6.5), LEFT)\n        self.play(FadeIn(summary2))\n        self.wait(2)\n        self.play(FadeOut(summary),FadeOut(summary1),FadeOut(summary2))\n        \n        summary = TextMobject("DWL is found")\n        summary.move_to(self.coords_to_point(65, 10), LEFT)\n        self.play(FadeIn(summary))\n        summary1 = TextMobject("1) Between S and D curves")\n        summary1.move_to(self.coords_to_point(70, 8), LEFT)\n        self.play(FadeIn(summary1))\n        summary2 = TextMobject("2) Above the lost quantity")\n        summary2.move_to(self.coords_to_point(70, 6.5), LEFT)\n        self.play(FadeIn(summary2))\n        self.wait(2)\n        self.play(FadeOut(summary),FadeOut(summary1),FadeOut(summary2))\n        \n        reading = TextMobject("More info: Mankiw Ch. 7 + 8")\n        reading.move_to(self.coords_to_point(65, 10), LEFT)\n        self.play(FadeIn(reading))\n')


